pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, address receiver, uint256 amount) public {
        vm.assume(receiver != address(0));
        amount = bound(amount, 1, type(uint256).max);
        // actor is the caller; we need them to have enough balance for the transfer
        vm.deal(actor, amount);
        vm.deal(address(c), 0); // ensure contract starts with 0 balance for clean check?
        // We check the invariant: call succeeds (no revert) iff actor is the original deployer (owner)
        // First, determine if actor is the owner
        bool isOwner = (actor == address(this)); // setUp() deploys c, so Test contract is the owner
        bool ok;
        vm.prank(actor);
        try c.sendTo(receiver, amount) {
            ok = true;
        } catch {
            ok = false;
        }
        // The rule: the call reverts exactly when actor is not the owner.
        // That is, ok == true <==> isOwner == true.
        assertTrue(ok == isOwner);
    }
}

